import "../styles/Contact.css";
import { useState } from "react";
import { submitContactForm } from "../services/contactService";

function Contact() {

    const [formData, setFormData] = useState({
        fullName: "",
        email: "",
        requestType: "Collaboration",
        subject: "",
        message: "",
        platformUsername: "",
        budgetRange: "",
        preferredContactMethod: ""
    });

    const [statusMessage, setStatusMessage] = useState("");
    const [isSuccess, setIsSuccess] = useState(false);
    const [isSubmitting, setIsSubmitting] = useState(false);

    function handleInputChange(event) {
        const name = event.target.name;
        const value = event.target.value;

        setFormData(function(prevFormData) {
            return {
                ...prevFormData,
                [name]: value
            };
        });
    }

    function handleBudgetClick(budget) {
        setFormData(function(prevFormData) {
            return {
                ...prevFormData,
                budgetRange: budget
            };
        });
    }

    function handleReset() {
        setFormData({
            fullName: "",
            email: "",
            requestType: "Collaboration",
            subject: "",
            message: "",
            platformUsername: "",
            budgetRange: "",
            preferredContactMethod: ""
        });

        setStatusMessage("");
        setIsSuccess(false);
    }

    async function handleSubmit(event) {
        event.preventDefault();

        setStatusMessage("");
        setIsSuccess(false);

        if (formData.fullName.trim() === "") {
            setStatusMessage("Please enter your full name.");
            return;
        }

        if (formData.email.trim() === "") {
            setStatusMessage("Please enter your email address.");
            return;
        }

        if (formData.subject.trim() === "") {
            setStatusMessage("Please enter a subject.");
            return;
        }

        if (formData.message.trim() !== "" && formData.message.trim().length < 20) {
            setStatusMessage("If you enter a message, it must be at least 20 characters.");
            return;
        }

        try {
            setIsSubmitting(true);

            await submitContactForm(formData);

            setIsSuccess(true);
            setStatusMessage("Your request was submitted successfully.");

            setFormData({
                fullName: "",
                email: "",
                requestType: "Collaboration",
                subject: "",
                message: "",
                platformUsername: "",
                budgetRange: "",
                preferredContactMethod: ""
            });

        } catch (error) {
            setStatusMessage("There was a problem submitting your request.");
            setIsSuccess(false);
        } finally {
            setIsSubmitting(false);
        }
    }

    return (
        <div className="contact-page">

            <div className="contact-header">
                <h1>Contact</h1>

                <p className="contact-subtitle">
                    Requests, collaborations, and professional inquiries.
                </p>
            </div>

            <div className="page-divider">
                <span className="divider-mark"></span>
            </div>

            <form className="contact-form-box" onSubmit={handleSubmit}>

                <div className="contact-row">

                    <div className="contact-field">
                        <label>
                            Full Name <span>*</span>
                        </label>
                        <input
                            type="text"
                            name="fullName"
                            value={formData.fullName}
                            onChange={handleInputChange}
                        />
                    </div>

                    <div className="contact-field">
                        <label>
                            Email Address <span>*</span>
                        </label>
                        <input
                            type="email"
                            name="email"
                            value={formData.email}
                            onChange={handleInputChange}
                        />
                    </div>

                </div>

                <div className="contact-field">
                    <label>
                        Request Type <span>*</span>
                    </label>

                    <div className="select-wrap">
                        <select
                            name="requestType"
                            value={formData.requestType}
                            onChange={handleInputChange}
                        >
                            <option>Collaboration</option>
                            <option>Merch Request</option>
                            <option>Sponsorship / Business</option>
                            <option>Content Suggestion</option>
                            <option>Technical / Website Issue</option>
                            <option>Other</option>
                        </select>
                    </div>
                </div>

                <div className="contact-field">
                    <label>
                        Subject <span>*</span>
                    </label>
                    <input
                        type="text"
                        name="subject"
                        value={formData.subject}
                        onChange={handleInputChange}
                    />
                </div>

                <div className="contact-field">
                    <label>
                        Message <span className="optional">(optional)</span>
                    </label>
                    <textarea
                        name="message"
                        value={formData.message}
                        onChange={handleInputChange}
                        placeholder="Enter at least 20 characters"
                    ></textarea>
                </div>

                <div className="contact-row">

                    <div className="contact-field">
                        <label>
                            Platform Username <span className="optional">(optional)</span>
                        </label>
                        <input
                            type="text"
                            name="platformUsername"
                            value={formData.platformUsername}
                            onChange={handleInputChange}
                            placeholder="Your Twitch, Discord, etc. username"
                        />
                    </div>

                    <div className="contact-field">
                        <label>
                            Budget Range <span className="optional">(optional)</span>
                        </label>

                        <div className="budget-buttons">
                            <button
                                type="button"
                                className={formData.budgetRange === "$0-$50" ? "budget-btn active-budget" : "budget-btn"}
                                onClick={function() { handleBudgetClick("$0-$50"); }}
                            >
                                $0-$50
                            </button>

                            <button
                                type="button"
                                className={formData.budgetRange === "$50-$250" ? "budget-btn active-budget" : "budget-btn"}
                                onClick={function() { handleBudgetClick("$50-$250"); }}
                            >
                                $50-$250
                            </button>

                            <button
                                type="button"
                                className={formData.budgetRange === "$250-$1,000+" ? "budget-btn active-budget" : "budget-btn"}
                                onClick={function() { handleBudgetClick("$250-$1,000+"); }}
                            >
                                $250-$1,000+
                            </button>
                        </div>
                    </div>

                </div>

                <div className="contact-bottom-row">

                    <div className="contact-method-box">
                        <label>Preferred Contact Method</label>

                        <div className="preferred-options">

                            <label className="radio-label">
                                <input
                                    type="radio"
                                    name="preferredContactMethod"
                                    value="Email"
                                    checked={formData.preferredContactMethod === "Email"}
                                    onChange={handleInputChange}
                                />
                                Email
                            </label>

                            <label className="radio-label">
                                <input
                                    type="radio"
                                    name="preferredContactMethod"
                                    value="Discord"
                                    checked={formData.preferredContactMethod === "Discord"}
                                    onChange={handleInputChange}
                                />
                                Discord
                            </label>

                        </div>
                    </div>

                    <div className="contact-buttons">
                        <button className="gold-btn" type="submit" disabled={isSubmitting}>
                            {isSubmitting ? "Submitting..." : "Submit Request"}
                        </button>

                        <button
                            className="gold-btn gold-btn-reset"
                            type="button"
                            onClick={handleReset}
                        >
                            Reset
                        </button>
                    </div>

                </div>

                {statusMessage !== "" && (
                    <p className={isSuccess ? "contact-status success-message" : "contact-status error-message"}>
                        {statusMessage}
                    </p>
                )}

                <p className="contact-note">
                    This form is protected by reCAPTCHA and subject to the BL Studio Privacy Policy.
                </p>

            </form>

        </div>
    );
}

